mapper.select:
SELECT A.OFFICE_CODE AS OFFICE_CODE, A.DOC_SEQ AS DOC_SEQ, A.DOC_GBN AS DOC_GBN, B.DOC_GBN_NAME AS DOC_GBN_NAME, A.MAKE_DATE AS MAKE_DATE, A.DOC_FOLDER AS DOC_FOLDER, A.MGM_DEPT_CD AS MGM_DEPT_CD, C.DEPT_NAME AS MGM_DEPT_NM, A.DOC_STORAGE AS DOC_STORAGE, D.STORAGE_NAME AS DOC_STORAGE_NAME, A.STORAGE_MAX_YEAR AS STORAGE_MAX_YEAR, A.DISUSE_PLAN_DATE AS DISUSE_PLAN_DATE, A.REMARKS AS REMARKS, ISNULL(A.DISUSE_YN,'N') AS DISUSE_YN, A.DISUSE_DATE AS DISUSE_DATE, A.DISUSE_REASON AS DISUSE_REASON FROM dbo.TAD_MAKE_DOC A LEFT JOIN dbo.TAD_MAKE_DOC_GBN B ON A.OFFICE_CODE = B.OFFICE_CODE AND A.DOC_GBN = B.DOC_GBN LEFT JOIN dbo.THR_DEPT C ON A.OFFICE_CODE = C.OFFICE_CODE AND A.MGM_DEPT_CD = C.DEPT_CD LEFT JOIN dbo.TAD_DOC_STORAGE D ON A.OFFICE_CODE = D.OFFICE_CODE AND A.DOC_STORAGE = D.STORAGE_CD WHERE A.OFFICE_CODE = #{LOGINUSER_OFFICE_CODE} AND ISNULL(A.DISUSE_YN,'N') = 'Y' AND NULLIF(LTRIM(RTRIM(A.DISUSE_DATE)), '') IS NOT NULL
AND A.DISUSE_DATE > #{START_DATE}
AND A.DISUSE_DATE <= #{END_DATE}
ORDER BY CONVERT(INT,A.DISUSE_DATE) DESC

